import java.io.BufferedReader
import java.io.InputStreamReader
import kotlin.math.max

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val n = br.readLine().trim().toInt()

    // Total segments: all [i, j] with 0 <= i < j <= N
    val segments = mutableListOf<Pair<Int, Int>>()
    for (i in 0 until n) {
        for (j in i + 1..n) {
            segments.add(Pair(i, j))
        }
    }

    // Sort segments by length descending, then by start
    segments.sortWith(compareByDescending<Pair<Int, Int>> { it.second - it.first }.thenBy { it.first })

    val layers = mutableListOf<MutableList<Pair<Int, Int>>>()

    for (seg in segments) {
        var placed = false
        for (layer in layers) {
            var ok = true
            for (s in layer) {
                // Check overlap: interiors intersect
                if (max(seg.first, s.first) < minOf(seg.second, s.second)) {
                    ok = false
                    break
                }
            }
            if (ok) {
                layer.add(seg)
                placed = true
                break
            }
        }
        if (!placed) {
            val newLayer = mutableListOf<Pair<Int, Int>>()
            newLayer.add(seg)
            layers.add(newLayer)
        }
    }

    println(layers.size)
}

