import kotlin.math.max

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val n = br.readLine().trim().toInt()

    // Total segments: all [i, j] with 0 <= i < j <= n
    // Minimal layers equals maximum number of overlapping segments at any point.
    // For integer points x in [0, n], count segments containing x.
    // A segment [i, j] contains x if i <= x <= j.
    // For fixed x, i ranges from 0..x, j from x+1..n.
    // Count = (x + 1) * (n - x)
    var ans = 0
    for (x in 0..n) {
        val count = (x + 1) * (n - x)
        ans = max(ans, count)
    }
