import java.io.BufferedReader
import java.io.InputStreamReader
import kotlin.math.max

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val n = br.readLine().trim().toInt()

    val segments = mutableListOf<Pair<Int, Int>>()
    for (i in 0..n) {
        for (j in i + 1..n) {
            segments.add(Pair(i, j))
        }
    }

    val layers = mutableListOf<MutableList<Pair<Int, Int>>>()

    fun overlaps(a: Pair<Int, Int>, b: Pair<Int, Int>): Boolean {
        val (a1, a2) = a
        val (b1, b2) = b
        return max(a1, b1) < minOf(a2, b2)
    }

    for (seg in segments) {
        var placed = false
        for (layer in layers) {
            var ok = true
            for (s in layer) {
                if (overlaps(seg, s)) {
                    ok = false
                    break
                }
            }
            if (ok) {
                layer.add(seg)
                placed = true
                break
            }
        }
        if (!placed) {
            layers.add(mutableListOf(seg))
        }
    }

    println(layers.size)
}

import java.io.BufferedReader
import java.io.InputStreamReader
import kotlin.math.max

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val n = br.readLine().trim().toInt()

    // We need the maximum number of segments covering any point.
    // For integer points x in [0, n], count segments [i, j] with i < j, 0<=i<j<=n, and i <= x <= j.
    var answer = 0
    for (x in 0..n) {
        val leftChoices = x + 1      // i from 0..x
        val rightChoices = n - x + 1 // j from x..n
        val totalSegmentsCoveringX = leftChoices * rightChoices - 1 // subtract the degenerate [x,x]
        answer = max(answer, totalSegmentsCoveringX)
    }

    println(answer)
}

import java.io.BufferedReader
import java.io.InputStreamReader
import kotlin.math.max

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val n = br.readLine().trim().toInt()

    // We need the maximum number of overlapping segments at any point.
    // Segments are all [i, j] with 0 <= i < j <= n.
    // For any integer point x (0..n), count segments containing x.
    var answer = 0
    for (x in 0..n) {
        var count = 0
        for (i in 0 until n) {
            for (j in i + 1..n) {
                if (x in i..j) count++
            }
        }
        answer = max(answer, count)
    }

    println(answer)
}
